-- One invite code per user (PLAN-next "门户下一批", 2026-10-14): every
-- role=user account has exactly one code, created automatically the first
-- time the portal asks for it while registration is open; it can be neither
-- deleted nor regenerated by the user (`DELETE /me/invite-codes/{code}` is
-- gone, a second `POST /me/invite-codes` answers 409 `invite.exists`).
--
-- Accounts that already hold several codes keep all of them (links already
-- shared keep working); the portal shows the oldest one that still admits a
-- registration as "your code".
--
-- `signup_settings.invite_codes_per_user` (the per-user limit, 0–100) has
-- nothing left to limit, and `users.invite_autocreated` (W20: the automatic
-- first code is made once, so a user who deleted their codes does not get
-- them back) has nothing left to remember: both are dropped.

ALTER TABLE signup_settings DROP COLUMN invite_codes_per_user;
ALTER TABLE users DROP COLUMN invite_autocreated;
